<?phpif ( ! defined( 'ABSPATH' ) ) {    exit;}if ( ! is_admin() || ! current_user_can( 'manage_options' ) ) {    echo 'Direct access not allowed.';    exit;}global $wpdb;cpabc_appointments_ensure_ipn_security_schema();$error_log_table     = $wpdb->prefix . 'cpabc_paypal_ipn_error_log';$calendars_table     = CPABC_APPOINTMENTS_CONFIG_TABLE_NAME;$appointments_table  = CPABC_APPOINTMENTS_TABLE_NAME;$calendar_data_table = CPABC_TDEAPP_CALENDAR_DATA_TABLE;$verify_nonce = ( ! empty( $_REQUEST['_wpnonce'] ) ) ? wp_verify_nonce( sanitize_text_field( wp_unslash( $_REQUEST['_wpnonce'] ) ), 'cpabc_ipn_logs_action' ) : false;$message      = '';$message_type = 'success';// Action 1: Delete single log entryif ( isset( $_GET['del_id'] ) && $verify_nonce ) {    $wpdb->delete( $error_log_table, array( 'id' => intval( $_GET['del_id'] ) ), array( '%d' ) );    $message = __( 'Log entry deleted.', 'appointment-booking-calendar' );}// Action 2: Clear all logsif ( isset( $_GET['clear_logs'] ) && $_GET['clear_logs'] === '1' && $verify_nonce ) {    $wpdb->query( "TRUNCATE TABLE `{$error_log_table}`" );    $message = __( 'All IPN error logs have been cleared.', 'appointment-booking-calendar' );}// Action 3: Update Calendar PayPal Email to Primary Email reported by PayPalif ( isset( $_POST['cpabc_action'] ) && $_POST['cpabc_action'] === 'use_primary_email' && $verify_nonce ) {    $target_cal_id = intval( $_POST['calendar_id'] );    $primary_email = sanitize_email( wp_unslash( $_POST['primary_email'] ) );    if ( $target_cal_id > 0 && is_email( $primary_email ) ) {        $wpdb->update(            $calendars_table,            array( 'paypal_email' => $primary_email ),            array( 'id' => $target_cal_id ),            array( '%s' ),            array( '%d' )        );        $message = sprintf( __( 'Calendar #%1$d PayPal email setting updated to primary email: %2$s', 'appointment-booking-calendar' ), $target_cal_id, $primary_email );    }}// Action 4: Manually mark a legitimate booking batch as Paid/Confirmed and send confirmation emailsif ( isset( $_POST['cpabc_action'] ) && $_POST['cpabc_action'] === 'mark_paid' && $verify_nonce ) {    $log_id     = intval( $_POST['log_id'] );    $booking_id = intval( $_POST['booking_id'] );    $log_row    = $wpdb->get_row( $wpdb->prepare( "SELECT * FROM `{$error_log_table}` WHERE id = %d LIMIT 1", $log_id ) );    $sub_row    = $wpdb->get_row( $wpdb->prepare( "SELECT * FROM `{$appointments_table}` WHERE id = %d LIMIT 1", $booking_id ) );    if ( $sub_row ) {        if ( ! empty( $sub_row->ipn_token ) ) {            $batch_rows = $wpdb->get_results(                $wpdb->prepare( "SELECT * FROM `{$appointments_table}` WHERE ipn_token = %s ORDER BY id ASC", $sub_row->ipn_token )            );        } else {            $batch_rows = array( $sub_row );        }        $batch_ids = array();        foreach ( $batch_rows as $b_row ) {            $batch_ids[] = intval( $b_row->id );        }        $placeholders  = implode( ',', array_fill( 0, count( $batch_ids ), '%s' ) );        $existing_refs = intval( $wpdb->get_var(            $wpdb->prepare(                "SELECT COUNT(*) FROM `{$calendar_data_table}` WHERE reference IN ($placeholders)",                array_map( 'strval', $batch_ids )            )        ) );        if ( $existing_refs === 0 ) {            $txn_id           = ( $log_row && $log_row->txn_id !== '' ) ? $log_row->txn_id : 'MANUAL_' . time();            $itemparam_string = implode( ';', $batch_ids );            foreach ( $batch_rows as $b_row ) {                $row_params = @unserialize( $b_row->buffered_date, array( 'allowed_classes' => false ) );                if ( ! is_array( $row_params ) ) {                    $row_params = array();                }                $row_params['txnid'] = $txn_id;                $wpdb->update(                    $appointments_table,                    array(                        'buffered_date' => serialize( $row_params ),                        'txnid'         => $txn_id,                    ),                    array( 'id' => intval( $b_row->id ) ),                    array( '%s', '%s' ),                    array( '%d' )                );            }            $ipn_table = $wpdb->prefix . 'cpabc_paypal_ipn_log';            if ( ! empty( $sub_row->ipn_token ) ) {                $wpdb->query(                    $wpdb->prepare(                        "INSERT IGNORE INTO `{$ipn_table}` (txn_id, ipn_token, booking_ids, created_at) VALUES (%s, %s, %s, %s)",                        $txn_id,                        $sub_row->ipn_token,                        $itemparam_string,                        current_time( 'mysql' )                    )                );            }            // Ensure cpabc_process_ready_to_go_appointment sends confirmation emails when called from wp-admin            $_POST['sendemails_admin'] = '1';            cpabc_process_ready_to_go_appointment( $itemparam_string, '' );            $message = sprintf( __( 'Booking #%1$s has been confirmed as PAID (Transaction ID: %2$s), added to the calendar schedule, and notification emails have been sent.', 'appointment-booking-calendar' ), $itemparam_string, $txn_id );        } else {            $message      = __( 'This booking is already confirmed on the calendar.', 'appointment-booking-calendar' );            $message_type = 'warning';        }    } else {        $message      = __( 'Booking record was not found.', 'appointment-booking-calendar' );        $message_type = 'warning';    }}// Filters & Pagination$filter_cal    = isset( $_GET['cal_id'] ) ? intval( $_GET['cal_id'] ) : 0;$filter_search = isset( $_GET['s_ipn'] ) ? sanitize_text_field( wp_unslash( $_GET['s_ipn'] ) ) : '';$current_page  = isset( $_GET['paged'] ) ? max( 1, intval( $_GET['paged'] ) ) : 1;$per_page      = 25;$offset        = ( $current_page - 1 ) * $per_page;$where_clauses = array( '1=1' );$where_values  = array();if ( $filter_cal > 0 ) {    $where_clauses[] = 'l.calendar_id = %d';    $where_values[]  = $filter_cal;}if ( $filter_search !== '' ) {    $like            = '%' . $wpdb->esc_like( $filter_search ) . '%';    $where_clauses[] = '(l.txn_id LIKE %s OR l.payer_email LIKE %s OR l.receiver_email LIKE %s OR l.business_email LIKE %s OR l.error_code LIKE %s OR l.custom_token LIKE %s)';    array_push( $where_values, $like, $like, $like, $like, $like, $like );}$where_sql = implode( ' AND ', $where_clauses );$count_query = "SELECT COUNT(*) FROM `{$error_log_table}` l WHERE {$where_sql}";$total_items = ! empty( $where_values ) ? intval( $wpdb->get_var( $wpdb->prepare( $count_query, $where_values ) ) ) : intval( $wpdb->get_var( $count_query ) );$total_pages = max( 1, ceil( $total_items / $per_page ) );$list_query = "SELECT l.*,                      c.uname AS calendar_name,                      p.txnid AS booking_txnid,                      p.booked_time AS booking_time,                      p.name AS booking_customer_name,                      p.email AS booking_customer_email,                      p.phone AS booking_customer_phone,                      p.question AS booking_question,                      (SELECT COUNT(*) FROM `{$calendar_data_table}` d WHERE d.reference = CAST(l.booking_id AS CHAR)) AS confirmed_count               FROM `{$error_log_table}` l               LEFT JOIN `{$calendars_table}` c ON l.calendar_id = c.id               LEFT JOIN `{$appointments_table}` p ON l.booking_id = p.id               WHERE {$where_sql}               ORDER BY l.id DESC               LIMIT %d OFFSET %d";$query_params   = array_merge( $where_values, array( $per_page, $offset ) );$logs           = $wpdb->get_results( $wpdb->prepare( $list_query, $query_params ) );$calendars_list = $wpdb->get_results( "SELECT id, uname FROM `{$calendars_table}` ORDER BY id ASC" );$nonce          = wp_create_nonce( 'cpabc_ipn_logs_action' );?><style>    .cpabc-admin-wrap { max-width: 1380px; margin-top: 20px; }    .cpabc-header { display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 12px; margin-bottom: 20px; }    .cpabc-header-title { display: flex; align-items: center; gap: 12px; }    .cpabc-header-title h1 { margin: 0; padding: 0; font-size: 23px; font-weight: 600; line-height: 1.3; }    .cpabc-header-subtitle { margin: 4px 0 0 0; color: #50575e; font-size: 13px; }    .cpabc-header-actions { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }    .cpabc-card { background: #fff; border: 1px solid #c3c4c7; border-radius: 6px; box-shadow: 0 1px 2px rgba(0,0,0,0.04); margin-bottom: 20px; overflow: hidden; }    .cpabc-card-header { display: flex; align-items: center; justify-content: space-between; padding: 14px 20px; border-bottom: 1px solid #dcdcde; background: #f6f7f7; }    .cpabc-card-header h2 { margin: 0; font-size: 15px; font-weight: 600; color: #1d2327; display: inline-flex; align-items: center; gap: 8px; }    .cpabc-badge-count { background: #e5e5e5; color: #1d2327; border-radius: 12px; padding: 2px 10px; font-size: 12px; font-weight: 600; }    .cpabc-btn { display: inline-flex !important; align-items: center !important; gap: 5px; }    .cpabc-btn-danger { color: #d63638 !important; border-color: #d63638 !important; }    .cpabc-btn-danger:hover { background: #d63638 !important; color: #fff !important; }    .cpabc-table-responsive { overflow-x: auto; }    .cpabc-table { border: none !important; margin: 0 !important; width: 100%; }    .cpabc-table thead th { font-weight: 600; color: #1d2327; padding: 12px 14px !important; border-bottom: 1px solid #c3c4c7; }    .cpabc-table tbody td { padding: 12px 14px !important; vertical-align: top; }</style><div class="wrap cpabc-admin-wrap">    <?php if ( $message ) : ?>        <div class="notice notice-<?php echo esc_attr( $message_type ); ?> is-dismissible" style="margin: 0 0 20px 0;">            <p><strong><?php echo esc_html( $message ); ?></strong></p>        </div>    <?php endif; ?>    <!-- Header -->    <div class="cpabc-header">        <div class="cpabc-header-title">            <span class="dashicons dashicons-warning" style="font-size: 32px; width: 32px; height: 32px; color: #dba617;"></span>            <div>                <h1><?php esc_html_e( 'PayPal IPN Diagnostic & Error Logs', 'appointment-booking-calendar' ); ?></h1>                <p class="cpabc-header-subtitle"><?php esc_html_e( 'Detailed diagnostics for failed or rejected PayPal Instant Payment Notifications (IPN), transaction identification, and one-click booking recovery.', 'appointment-booking-calendar' ); ?></p>            </div>        </div>        <div class="cpabc-header-actions">            <a href="admin.php?page=cpabc_appointments.php" class="button button-secondary cpabc-btn-icon">                <span class="dashicons dashicons-arrow-left-alt2" aria-hidden="true"></span>                <span><?php esc_html_e( 'Back to Calendar List', 'appointment-booking-calendar' ); ?></span>            </a>            <?php if ( $total_items > 0 ) : ?>                <a href="<?php echo esc_url( wp_nonce_url( 'admin.php?page=cpabc_appointments_ipn_logs&clear_logs=1', 'cpabc_ipn_logs_action' ) ); ?>"                   class="button cpabc-btn cpabc-btn-danger"                   onclick="return confirm('<?php echo esc_js( __( 'Are you sure you want to clear all IPN error logs?', 'appointment-booking-calendar' ) ); ?>');">                    <span class="dashicons dashicons-trash" aria-hidden="true"></span>                    <?php esc_html_e( 'Clear All Logs', 'appointment-booking-calendar' ); ?>                </a>            <?php endif; ?>        </div>    </div>    <!-- Tip Callout for Multiple PayPal Emails -->    <div class="cpabc-card" style="border-left: 4px solid #dba617;">        <div style="padding: 14px 20px;">            <strong><?php esc_html_e( 'Note on Multiple PayPal Email Addresses:', 'appointment-booking-calendar' ); ?></strong>            <?php esc_html_e( 'If your PayPal account has multiple email addresses configured, PayPal always sends the PRIMARY email address of the PayPal account as the "receiver_email" in IPN notifications. Always specify your primary PayPal email address in each calendar\'s "PayPal Email" setting.', 'appointment-booking-calendar' ); ?>        </div>    </div>    <!-- Filter Bar -->    <div class="cpabc-card">        <div style="padding: 16px 20px;">            <form method="get" action="admin.php" style="display: flex; gap: 12px; align-items: center; flex-wrap: wrap;">                <input type="hidden" name="page" value="cpabc_appointments_ipn_logs" />                <label for="filter_cal_id" style="font-weight: 600;"><?php esc_html_e( 'Calendar:', 'appointment-booking-calendar' ); ?></label>                <select name="cal_id" id="filter_cal_id" style="max-width: 240px;">                    <option value="0"><?php esc_html_e( 'All Calendars', 'appointment-booking-calendar' ); ?></option>                    <?php foreach ( $calendars_list as $cal ) : ?>                        <option value="<?php echo intval( $cal->id ); ?>" <?php selected( $filter_cal, intval( $cal->id ) ); ?>>                            #<?php echo intval( $cal->id ); ?> - <?php echo esc_html( $cal->uname ); ?>                        </option>                    <?php endforeach; ?>                </select>                <label for="s_ipn" style="font-weight: 600;"><?php esc_html_e( 'Search:', 'appointment-booking-calendar' ); ?></label>                <input type="text" name="s_ipn" id="s_ipn" value="<?php echo esc_attr( $filter_search ); ?>" placeholder="<?php esc_attr_e( 'Txn ID, Payer Email, Receiver Email, Error...', 'appointment-booking-calendar' ); ?>" style="min-width: 280px;" />                <button type="submit" class="button button-primary cpabc-btn">                    <span class="dashicons dashicons-search" aria-hidden="true"></span>                    <?php esc_html_e( 'Filter Logs', 'appointment-booking-calendar' ); ?>                </button>                <?php if ( $filter_cal > 0 || $filter_search !== '' ) : ?>                    <a href="admin.php?page=cpabc_appointments_ipn_logs" class="button cpabc-btn"><?php esc_html_e( 'Reset', 'appointment-booking-calendar' ); ?></a>                <?php endif; ?>            </form>        </div>    </div>    <!-- Logs Table -->    <div class="cpabc-card">        <div class="cpabc-card-header">            <h2>                <span class="dashicons dashicons-list-view" aria-hidden="true"></span>                <span><?php esc_html_e( 'Failed IPN Notifications Log', 'appointment-booking-calendar' ); ?></span>            </h2>            <span class="cpabc-badge-count"><?php echo intval( $total_items ); ?> <?php esc_html_e( 'Entries', 'appointment-booking-calendar' ); ?></span>        </div>        <div class="cpabc-table-responsive">            <table class="cpabc-table widefat striped">                <thead>                    <tr>                        <th style="width: 140px;"><?php esc_html_e( 'Date / HTTP', 'appointment-booking-calendar' ); ?></th>                        <th style="width: 220px;"><?php esc_html_e( 'Calendar & Booking', 'appointment-booking-calendar' ); ?></th>                        <th style="width: 240px;"><?php esc_html_e( 'Transaction & Emails', 'appointment-booking-calendar' ); ?></th>                        <th style="width: 170px;"><?php esc_html_e( 'Amount & Currency', 'appointment-booking-calendar' ); ?></th>                        <th><?php esc_html_e( 'Diagnostic Cause & How to Solve', 'appointment-booking-calendar' ); ?></th>                        <th style="width: 190px;"><?php esc_html_e( 'Actions', 'appointment-booking-calendar' ); ?></th>                    </tr>                </thead>                <tbody>                    <?php if ( ! empty( $logs ) ) : ?>                        <?php foreach ( $logs as $row ) :                            $is_email_mismatch = in_array( $row->error_code, array( 'merchant_email_mismatch', 'receiver_email_mismatch' ), true );                            $is_confirmed      = ( intval( $row->confirmed_count ) > 0 || ! empty( $row->booking_txnid ) );                            $can_mark_paid     = ( intval( $row->booking_id ) > 0 && ! $is_confirmed );                        ?>                            <tr>                                <!-- Date & HTTP Code -->                                <td>                                    <strong><?php echo esc_html( $row->created_at ); ?></strong><br />                                    <span style="display:inline-block; margin-top:4px; padding:2px 8px; border-radius:4px; font-size:11px; font-weight:600; background:<?php echo intval( $row->http_status ) >= 400 ? '#fcf0f1' : '#f0f6fc'; ?>; color:<?php echo intval( $row->http_status ) >= 400 ? '#d63638' : '#2271b1'; ?>;">                                        HTTP <?php echo intval( $row->http_status ); ?>                                    </span>                                    <div style="font-size: 11px; color: #646970; margin-top: 4px;">                                        IP: <?php echo esc_html( $row->ip_address ); ?>                                    </div>                                </td>                                <!-- Calendar & Booking -->                                <td>                                    <?php if ( intval( $row->calendar_id ) > 0 ) : ?>                                        <div>                                            <strong><?php esc_html_e( 'Calendar:', 'appointment-booking-calendar' ); ?></strong>                                            <a href="admin.php?page=cpabc_appointments.php&cal=<?php echo intval( $row->calendar_id ); ?>">                                                #<?php echo intval( $row->calendar_id ); ?> <?php echo esc_html( $row->calendar_name ? $row->calendar_name : '' ); ?>                                            </a>                                        </div>                                    <?php else : ?>                                        <div><em><?php esc_html_e( 'Calendar: Unknown', 'appointment-booking-calendar' ); ?></em></div>                                    <?php endif; ?>                                    <?php if ( intval( $row->booking_id ) > 0 ) : ?>                                        <div style="margin-top: 4px;">                                            <strong><?php esc_html_e( 'Booking:', 'appointment-booking-calendar' ); ?></strong>                                            <a href="admin.php?page=cpabc_appointments.php&cal=<?php echo intval( $row->calendar_id ); ?>&list=1">                                                #<?php echo esc_html( $row->booking_ids ? $row->booking_ids : $row->booking_id ); ?>                                            </a>                                            <?php if ( $is_confirmed ) : ?>                                                <span style="background:#edfaef; color:#008a20; padding:1px 6px; border-radius:3px; font-size:11px; font-weight:600;"><?php esc_html_e( 'PAID', 'appointment-booking-calendar' ); ?></span>                                            <?php else : ?>                                                <span style="background:#fcf9e8; color:#996800; padding:1px 6px; border-radius:3px; font-size:11px; font-weight:600;"><?php esc_html_e( 'UNPAID', 'appointment-booking-calendar' ); ?></span>                                            <?php endif; ?>                                        </div>                                        <?php if ( ! empty( $row->booking_time ) || ! empty( $row->booking_customer_email ) ) : ?>                                            <details style="margin-top: 6px; font-size: 12px;">                                                <summary style="cursor: pointer; color: #2271b1;"><?php esc_html_e( 'View Booking Details', 'appointment-booking-calendar' ); ?></summary>                                                <div style="background: #f6f7f7; padding: 8px; border-radius: 4px; font-size: 11px; margin-top: 4px; line-height: 1.5;">                                                    <div><strong><?php esc_html_e( 'Slot:', 'appointment-booking-calendar' ); ?></strong> <?php echo esc_html( $row->booking_time ); ?></div>                                                    <div><strong><?php esc_html_e( 'Name:', 'appointment-booking-calendar' ); ?></strong> <?php echo esc_html( $row->booking_customer_name ); ?></div>                                                    <div><strong><?php esc_html_e( 'Email:', 'appointment-booking-calendar' ); ?></strong> <?php echo esc_html( $row->booking_customer_email ); ?></div>                                                    <?php if ( ! empty( $row->booking_customer_phone ) ) : ?>                                                        <div><strong><?php esc_html_e( 'Phone:', 'appointment-booking-calendar' ); ?></strong> <?php echo esc_html( $row->booking_customer_phone ); ?></div>                                                    <?php endif; ?>                                                    <?php if ( ! empty( $row->booking_question ) ) : ?>                                                        <div><strong><?php esc_html_e( 'Notes:', 'appointment-booking-calendar' ); ?></strong> <?php echo esc_html( $row->booking_question ); ?></div>                                                    <?php endif; ?>                                                </div>                                            </details>                                        <?php endif; ?>                                    <?php else : ?>                                        <div style="margin-top: 4px; color: #646970; font-size: 12px;">                                            <?php esc_html_e( 'No matching booking row', 'appointment-booking-calendar' ); ?>                                        </div>                                    <?php endif; ?>                                </td>                                <!-- Transaction & Emails -->                                <td style="font-size: 12px; line-height: 1.5;">                                    <div><strong><?php esc_html_e( 'Txn ID:', 'appointment-booking-calendar' ); ?></strong> <code><?php echo esc_html( $row->txn_id ? $row->txn_id : 'N/A' ); ?></code></div>                                    <div><strong><?php esc_html_e( 'Status:', 'appointment-booking-calendar' ); ?></strong> <?php echo esc_html( $row->payment_status ? $row->payment_status : 'N/A' ); ?></div>                                    <div><strong><?php esc_html_e( 'Payer:', 'appointment-booking-calendar' ); ?></strong> <?php echo esc_html( $row->payer_email ? $row->payer_email : 'N/A' ); ?></div>                                    <hr style="margin: 6px 0; border: 0; border-top: 1px solid #dcdcde;" />                                    <div><strong><?php esc_html_e( 'Calendar Email:', 'appointment-booking-calendar' ); ?></strong> <?php echo esc_html( $row->expected_email ? $row->expected_email : 'N/A' ); ?></div>                                    <div><strong><?php esc_html_e( 'PayPal Primary (receiver_email):', 'appointment-booking-calendar' ); ?></strong> <span style="<?php echo $is_email_mismatch ? 'color:#d63638;font-weight:700;' : ''; ?>"><?php echo esc_html( $row->receiver_email ? $row->receiver_email : 'N/A' ); ?></span></div>                                    <?php if ( $row->business_email && $row->business_email !== $row->receiver_email ) : ?>                                        <div><strong><?php esc_html_e( 'PayPal Business:', 'appointment-booking-calendar' ); ?></strong> <?php echo esc_html( $row->business_email ); ?></div>                                    <?php endif; ?>                                </td>                                <!-- Amount & Currency -->                                <td style="font-size: 12px; line-height: 1.6;">                                    <div>                                        <strong><?php esc_html_e( 'Paid in PayPal:', 'appointment-booking-calendar' ); ?></strong><br />                                        <code><?php echo esc_html( ( $row->paid_amount !== '' ? $row->paid_amount : '0.00' ) . ' ' . $row->paid_currency ); ?></code>                                    </div>                                    <?php if ( $row->expected_amount !== '' || $row->expected_currency !== '' ) : ?>                                        <div style="margin-top: 4px;">                                            <strong><?php esc_html_e( 'Expected by Calendar:', 'appointment-booking-calendar' ); ?></strong><br />                                            <code><?php echo esc_html( $row->expected_amount . ' ' . $row->expected_currency ); ?></code>                                        </div>                                    <?php endif; ?>                                </td>                                <!-- Diagnostic Cause & Resolution -->                                <td>                                    <div style="margin-bottom: 6px;">                                        <code style="background: #fcf0f1; color: #d63638; font-weight: 600; padding: 2px 6px; border-radius: 3px;">                                            <?php echo esc_html( $row->error_code ); ?>                                        </code>                                    </div>                                    <div style="font-weight: 600; color: #1d2327; margin-bottom: 6px;">                                        <?php echo esc_html( $row->error_message ); ?>                                    </div>                                    <?php if ( ! empty( $row->resolution_hint ) ) : ?>                                        <div style="background: #f0f6fc; border-left: 3px solid #2271b1; padding: 8px 10px; font-size: 12px; color: #1d2327; margin-bottom: 6px;">                                            <strong><?php esc_html_e( 'How to resolve:', 'appointment-booking-calendar' ); ?></strong>                                            <?php echo esc_html( $row->resolution_hint ); ?>                                        </div>                                    <?php endif; ?>                                    <?php if ( ! empty( $row->raw_payload ) ) : ?>                                        <details style="font-size: 12px; margin-top: 4px;">                                            <summary style="cursor: pointer; color: #2271b1;"><?php esc_html_e( 'Inspect Full PayPal IPN Payload', 'appointment-booking-calendar' ); ?></summary>                                            <pre style="white-space: pre-wrap; background: #1d2327; color: #f0f0f1; padding: 10px; border-radius: 4px; font-size: 11px; max-height: 220px; overflow: auto; margin-top: 6px;"><?php echo esc_html( $row->raw_payload ); ?></pre>                                        </details>                                    <?php endif; ?>                                </td>                                <!-- Actions -->                                <td>                                    <div style="display: flex; flex-direction: column; gap: 6px;">                                        <?php if ( $is_email_mismatch && intval( $row->calendar_id ) > 0 && is_email( $row->receiver_email ) ) : ?>                                            <form method="post" action="admin.php?page=cpabc_appointments_ipn_logs" style="margin:0;">                                                <input type="hidden" name="_wpnonce" value="<?php echo esc_attr( $nonce ); ?>" />                                                <input type="hidden" name="cpabc_action" value="use_primary_email" />                                                <input type="hidden" name="calendar_id" value="<?php echo intval( $row->calendar_id ); ?>" />                                                <input type="hidden" name="primary_email" value="<?php echo esc_attr( $row->receiver_email ); ?>" />                                                <button type="submit" class="button cpabc-btn" style="width: 100%; justify-content: center;"                                                        onclick="return confirm('<?php echo esc_js( sprintf( __( 'Update Calendar #%1$d PayPal email to primary email %2$s?', 'appointment-booking-calendar' ), intval( $row->calendar_id ), $row->receiver_email ) ); ?>');">                                                    <?php esc_html_e( 'Set Primary Email in Calendar', 'appointment-booking-calendar' ); ?>                                                </button>                                            </form>                                        <?php endif; ?>                                        <?php if ( $can_mark_paid ) : ?>                                            <form method="post" action="admin.php?page=cpabc_appointments_ipn_logs" style="margin:0;">                                                <input type="hidden" name="_wpnonce" value="<?php echo esc_attr( $nonce ); ?>" />                                                <input type="hidden" name="cpabc_action" value="mark_paid" />                                                <input type="hidden" name="log_id" value="<?php echo intval( $row->id ); ?>" />                                                <input type="hidden" name="booking_id" value="<?php echo intval( $row->booking_id ); ?>" />                                                <button type="submit" class="button button-primary cpabc-btn" style="width: 100%; justify-content: center;"                                                        onclick="return confirm('<?php echo esc_js( sprintf( __( 'Mark Booking #%d as PAID, add to calendar, and send confirmation emails?', 'appointment-booking-calendar' ), intval( $row->booking_id ) ) ); ?>');">                                                    <?php esc_html_e( 'Mark Paid & Send Emails', 'appointment-booking-calendar' ); ?>                                                </button>                                            </form>                                        <?php endif; ?>                                        <a href="<?php echo esc_url( wp_nonce_url( 'admin.php?page=cpabc_appointments_ipn_logs&del_id=' . intval( $row->id ), 'cpabc_ipn_logs_action' ) ); ?>"                                           class="button cpabc-btn cpabc-btn-danger" style="text-align: center; justify-content: center;">                                            <?php esc_html_e( 'Delete Log', 'appointment-booking-calendar' ); ?>                                        </a>                                    </div>                                </td>                            </tr>                        <?php endforeach; ?>                    <?php else : ?>                        <tr>                            <td colspan="6" style="text-align: center; padding: 36px; color: #646970;">                                <?php esc_html_e( 'No failed IPN notifications recorded.', 'appointment-booking-calendar' ); ?>                            </td>                        </tr>                    <?php endif; ?>                </tbody>            </table>        </div>        <?php if ( $total_pages > 1 ) : ?>            <div style="padding: 14px 20px; display: flex; gap: 6px; align-items: center; justify-content: flex-end; border-top: 1px solid #dcdcde;">                <?php for ( $p = 1; $p <= $total_pages; $p++ ) :                    $page_url = add_query_arg(                        array(                            'page'   => 'cpabc_appointments_ipn_logs',                            'cal_id' => $filter_cal,                            's_ipn'  => $filter_search,                            'paged'  => $p,                        ),                        'admin.php'                    );                ?>                    <a href="<?php echo esc_url( $page_url ); ?>" class="button <?php echo $p === $current_page ? 'button-primary' : ''; ?>">                        <?php echo intval( $p ); ?>                    </a>                <?php endfor; ?>            </div>        <?php endif; ?>    </div></div>